
clear all, close all,

load('Q2data.mat','x','labels','gmmParameters');

visualizationFlag = 0;

C = 3;

lossMatrix10 = [0 1 10;
    1 0 10;
    1 1 0];

lossMatrix100 = [0 1 100;
    1 0 100;
    1 1 0];

[decisions10,confusionMatrix10] = ...
    performERMclassificationGMMdata(x,labels,gmmParameters,lossMatrix10,visualizationFlag);

[decisions100,confusionMatrix100] = ...
    performERMclassificationGMMdata(x,labels,gmmParameters,lossMatrix100,visualizationFlag);

disp('Confusion Matrix - Lambda 10:'); %[output:032c6391]
disp(confusionMatrix10); %[output:3d24e742]

disp('Confusion Matrix - Lambda 100:'); %[output:466d7073]
disp(confusionMatrix100); %[output:41a7c978]

classPriors = [0.3;0.3;0.4];

averageLoss10 = sum((lossMatrix10.*confusionMatrix10)*classPriors);
averageLoss100 = sum((lossMatrix100.*confusionMatrix100)*classPriors);

fprintf('\nAverage Loss - Lambda 10: %.6f\n',averageLoss10); %[output:6b2c3f48]
fprintf('Average Loss - Lambda 100: %.6f\n',averageLoss100); %[output:43af7d0c]


figure(1), clf, %[output:43a1fbe8]

subplot(1,2,1), %[output:43a1fbe8]
imagesc(confusionMatrix10), %[output:43a1fbe8]
colorbar, %[output:43a1fbe8]
title('Confusion Matrix - Lambda 10'), %[output:43a1fbe8]
xlabel('True Class'), %[output:43a1fbe8]
ylabel('Decision Class'), %[output:43a1fbe8]
axis square, %[output:43a1fbe8]

subplot(1,2,2), %[output:43a1fbe8]
imagesc(confusionMatrix100), %[output:43a1fbe8]
colorbar, %[output:43a1fbe8]
title('Confusion Matrix - Lambda 100'), %[output:43a1fbe8]
xlabel('True Class'), %[output:43a1fbe8]
ylabel('Decision Class'), %[output:43a1fbe8]
axis square, %[output:43a1fbe8]

exportgraphics(figure(1),'Q2_B_ConfusionMatrices.png','Resolution',300); %[output:43a1fbe8]

save('Q2_B_results.mat','decisions10','decisions100', ...
    'confusionMatrix10','confusionMatrix100', ...
    'averageLoss10','averageLoss100');


